CREATE OR REPLACE FUNCTION public._attach_role(p_membership_id uuid, p_role_key text, p_granted_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_team_id   uuid;
  v_singleton boolean;
begin
  select team_id into v_team_id
    from public.team_members where membership_id = p_membership_id;
  if v_team_id is null then
    raise exception 'No such membership %', p_membership_id using errcode = 'P0002';
  end if;

  select is_singleton into v_singleton
    from public.roles where scope = 'team' and key = p_role_key;
  if v_singleton is null then
    raise exception 'No such team role "%"', p_role_key using errcode = 'P0002';
  end if;

  -- The conflict target is the PRIMARY KEY and nothing else. A bare
  -- `on conflict do nothing` also swallows a violation of
  -- team_member_roles_singleton_per_team — so granting `captain` to a second
  -- person would report success and write nothing, which is how a silent
  -- failure gets shipped. Re-granting a role someone already holds is the only
  -- no-op; taking a singleton someone else holds must raise 23505.
  insert into public.team_member_roles
    (membership_id, scope, role_key, team_id, is_singleton, granted_by)
  values
    (p_membership_id, 'team', p_role_key, v_team_id, v_singleton, p_granted_by)
  on conflict (membership_id, scope, role_key) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public._fill_match_captains()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.team_a_id is not null and new.team_a_captain is null then
    new.team_a_captain := public._team_current_captain(new.team_a_id);
  end if;
  if new.team_b_id is not null and new.team_b_captain is null then
    new.team_b_captain := public._team_current_captain(new.team_b_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public._require_match_organizer(p_match_id uuid)
 RETURNS matches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_match public.matches;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select * into v_match from public.matches where match_id = p_match_id;

  if not found then
    raise exception 'Match not found' using errcode = 'P0002';
  end if;

  if v_match.tournament_id is null then
    raise exception 'Match is not part of a tournament' using errcode = '22023';
  end if;

  if not public.is_tournament_organizer(v_match.tournament_id) then
    raise exception 'Only tournament organizers can run live ops'
      using errcode = '42501';
  end if;

  return v_match;
end;
$function$

CREATE OR REPLACE FUNCTION public._validate_match_request_keeper()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Null keeper is always allowed (managers can ship a request without one
  -- and finalise on match day).
  if new.from_team_keeper_id is null then
    return new;
  end if;

  -- Keeper must appear in the picked XI. Mirrors the edge function's same
  -- check so a direct INSERT can't bypass it.
  if not (
    new.from_team_keeper_id = any(coalesce(new.from_team_xi, '{}'::uuid[]))
  ) then
    raise exception 'Wicket-keeper % is not in the picked XI',
      new.from_team_keeper_id
      using errcode = '23514';
  end if;

  -- Keeper must be a real, active member of the from-team — claimed OR
  -- unclaimed. Replaces the dropped FK's "is this person real?" guard.
  if not exists (
    select 1 from public.team_members tm
     where tm.team_id = new.from_team_id
       and (tm.user_id = new.from_team_keeper_id
            or tm.unclaimed_id = new.from_team_keeper_id)
       and tm.status = 'active'
  ) then
    raise exception 'Wicket-keeper % is not an active member of team %',
      new.from_team_keeper_id, new.from_team_id
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_dm_request(p_chat_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_now timestamptz := now();
begin
  if v_actor is null then
    raise exception 'Unauthenticated';
  end if;

  -- Ensure actor is a participant in this DM
  if not exists (
    select 1 from public.dm_channels
     where chat_id = p_chat_id
       and (user_a = v_actor or user_b = v_actor)
  ) then
    raise exception 'Not a participant in this DM chat';
  end if;

  -- Mark accepted in dm_channels
  update public.dm_channels
     set accepted_at = v_now,
         accepted_by = v_actor
   where chat_id = p_chat_id
     and accepted_at is null;

  -- Re-activate membership if previously left, and update last_read_at
  update public.chat_members
     set left_at = null,
         last_read_at = v_now
   where chat_id = p_chat_id
     and user_id = v_actor;

  return v_now;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_match_request(p_request_id uuid, p_scheduled_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_venue text DEFAULT NULL::text, p_format jsonb DEFAULT NULL::jsonb, p_decision_note text DEFAULT NULL::text, p_to_team_id uuid DEFAULT NULL::uuid, p_to_team_xi uuid[] DEFAULT '{}'::uuid[], p_to_team_keeper_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req         public.match_challenges%rowtype;
  v_to_team     uuid;
  v_match_id    uuid;
  v_format      jsonb;
  v_start       timestamptz;
  v_venue       text;
  v_to_team_xi  uuid[];
  v_to_keeper   uuid;
  v_a_captain   uuid;
  v_b_captain   uuid;
  v_updated     integer;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into v_req from public.match_challenges
   where request_id = p_request_id
   for update;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if v_req.status not in ('pending', 'countered') then
    raise exception 'Request is no longer actionable (status: %)', v_req.status
      using errcode = '22023';
  end if;

  if v_req.status = 'countered' then
    if not public.is_team_manager(v_req.from_team_id) then
      raise exception 'Only the original sender can accept a countered request'
        using errcode = '42501';
    end if;
    v_to_team    := v_req.to_team_id;
    v_format     := public._normalize_match_format(coalesce(p_format, v_req.countered_format, v_req.proposed_format, '{}'::jsonb));
    v_start      := coalesce(p_scheduled_start_time, v_req.countered_start_time, v_req.proposed_start_time);
    v_venue      := coalesce(p_venue, v_req.countered_venue, v_req.proposed_venue);
    v_to_team_xi := '{}'::uuid[];
    v_to_keeper  := null;
  elsif v_req.to_team_id is not null then
    if not public.is_team_manager(v_req.to_team_id) then
      raise exception 'Only managers of the receiving team can accept'
        using errcode = '42501';
    end if;
    v_to_team    := v_req.to_team_id;
    v_format     := public._normalize_match_format(coalesce(p_format, v_req.proposed_format, '{}'::jsonb));
    v_start      := coalesce(p_scheduled_start_time, v_req.proposed_start_time);
    v_venue      := coalesce(p_venue, v_req.proposed_venue);
    v_to_team_xi := coalesce(p_to_team_xi, '{}'::uuid[]);
    v_to_keeper  := p_to_team_keeper_id;
  else
    if p_to_team_id is null then
      raise exception 'Open requests require p_to_team_id to claim'
        using errcode = '22023';
    end if;
    if p_to_team_id = v_req.from_team_id then
      raise exception 'A team cannot accept its own challenge'
        using errcode = '23514';
    end if;
    if not public.is_team_manager(p_to_team_id) then
      raise exception 'You can only accept on behalf of teams you manage'
        using errcode = '42501';
    end if;
    v_to_team    := p_to_team_id;
    v_format     := public._normalize_match_format(coalesce(p_format, v_req.proposed_format, '{}'::jsonb));
    v_start      := coalesce(p_scheduled_start_time, v_req.proposed_start_time);
    v_venue      := coalesce(p_venue, v_req.proposed_venue);
    v_to_team_xi := coalesce(p_to_team_xi, '{}'::uuid[]);
    v_to_keeper  := p_to_team_keeper_id;
  end if;

  if v_to_team_xi is not null and array_length(v_to_team_xi, 1) is not null
     and array_length(v_to_team_xi, 1) > v_req.players_per_side then
    raise exception 'to_team_xi has more players than players_per_side'
      using errcode = '22023';
  end if;
  perform public._validate_team_xi(v_req.from_team_id, v_req.from_team_xi);
  perform public._validate_team_xi(v_to_team, v_to_team_xi);

  v_a_captain := public._team_current_captain(v_req.from_team_id);
  v_b_captain := public._team_current_captain(v_to_team);
  if v_a_captain is null or v_b_captain is null then
    raise exception 'Both teams must have a captain or owner before a match can be created'
      using errcode = '23502';
  end if;

  insert into public.matches (
    match_type, tournament_id,
    team_a_id, team_b_id,
    team_a_captain, team_b_captain,
    format, venue, scheduled_start_time,
    status, created_by
  ) values (
    'friendly', null,
    v_req.from_team_id, v_to_team,
    v_a_captain, v_b_captain,
    v_format, v_venue, v_start,
    'scheduled', auth.uid()
  )
  returning match_id into v_match_id;

  -- ---------------------------------------------------------------------------
  -- MATERIALISE THE PLAYING XIS INTO match_players
  --
  -- v1 UX never collects an XI up front — the captain picks openers from
  -- the full roster on the Lineup screen. So if the XI list is empty,
  -- default to "the team's full active roster". When the XI is non-empty
  -- (a future Pick-XI flow), filter to the picked players.
  --
  -- Polymorphism: tm.user_id XOR tm.unclaimed_id is already enforced by
  -- team_members, so each row satisfies the match_players XOR check.
  -- ---------------------------------------------------------------------------
  insert into public.match_players (
    match_id, team_side, user_id, unclaimed_id, display_name,
    role, is_in_playing_xi
  )
  select v_match_id, 'team_a',
         tm.user_id, tm.unclaimed_id,
         -- display_name is NOT NULL on match_players: the lineup keeps its
         -- own copy of the name so a match still reads correctly if the
         -- profile is later renamed, suspended or deleted.
         coalesce(pr.display_name, up.display_name, 'Player'),
         -- The new schema carries ONE role enum where the old one had two
         -- independent booleans, so a captain who also keeps wicket can no
         -- longer be both. Captain wins — it is the role that carries
         -- permissions (toss, openers, starting the match).
         case
           when tm.user_id = v_a_captain then 'captain'::public.match_role
           when tm.user_id = v_req.from_team_keeper_id or tm.unclaimed_id = v_req.from_team_keeper_id
             then 'wicket_keeper'::public.match_role
           else 'player'::public.match_role
         end,
         true
    from public.team_members tm
    left join public.profiles pr          on pr.user_id      = tm.user_id
    left join public.unclaimed_players up on up.unclaimed_id = tm.unclaimed_id
   where tm.team_id = v_req.from_team_id
     and tm.status  = 'active'
     and (
       -- Empty XI = include the full active roster.
       coalesce(array_length(v_req.from_team_xi, 1), 0) = 0
       -- Non-empty XI = filter to the picked players.
       or tm.user_id      = any(v_req.from_team_xi)
       or tm.unclaimed_id = any(v_req.from_team_xi)
     );

  insert into public.match_players (
    match_id, team_side, user_id, unclaimed_id, display_name,
    role, is_in_playing_xi
  )
  select v_match_id, 'team_b',
         tm.user_id, tm.unclaimed_id,
         -- display_name is NOT NULL on match_players: the lineup keeps its
         -- own copy of the name so a match still reads correctly if the
         -- profile is later renamed, suspended or deleted.
         coalesce(pr.display_name, up.display_name, 'Player'),
         -- The new schema carries ONE role enum where the old one had two
         -- independent booleans, so a captain who also keeps wicket can no
         -- longer be both. Captain wins — it is the role that carries
         -- permissions (toss, openers, starting the match).
         case
           when tm.user_id = v_b_captain then 'captain'::public.match_role
           when tm.user_id = v_to_keeper or tm.unclaimed_id = v_to_keeper
             then 'wicket_keeper'::public.match_role
           else 'player'::public.match_role
         end,
         true
    from public.team_members tm
    left join public.profiles pr          on pr.user_id      = tm.user_id
    left join public.unclaimed_players up on up.unclaimed_id = tm.unclaimed_id
   where tm.team_id = v_to_team
     and tm.status  = 'active'
     and (
       coalesce(array_length(v_to_team_xi, 1), 0) = 0
       or tm.user_id      = any(v_to_team_xi)
       or tm.unclaimed_id = any(v_to_team_xi)
     );

  -- Race guard: the inner UPDATE re-asserts the status we read above. If
  -- another concurrent transaction (counter / cancel / decline) already
  -- transitioned the row, our UPDATE matches zero rows and we roll back
  -- — preventing a match from being created against stale terms.
  update public.match_challenges
     set status        = 'accepted',
         decided_by    = auth.uid(),
         decided_at    = now(),
         decision_note = p_decision_note,
         match_id      = v_match_id,
         to_team_id    = v_to_team
   where request_id = p_request_id
     and status     = v_req.status;
  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    raise exception 'Request changed under us; aborting accept'
      using errcode = '40001';
  end if;

  return v_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_team_invite(p_invite_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid           uuid := auth.uid();
  v_team_id       uuid;
  v_invitee_id    uuid;
  v_role          text;
  v_jersey        integer;
  v_invited_by    uuid;
  v_membership_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select team_id, invitee_id, role, jersey_number, invited_by
    into v_team_id, v_invitee_id, v_role, v_jersey, v_invited_by
    from public.team_invites
   where invite_id = p_invite_id and status = 'pending'
   for update;
  if v_team_id is null then
    raise exception 'Invite not found or not pending'
      using errcode = 'P0002';
  end if;
  if v_invitee_id <> v_uid then
    raise exception 'Only the invitee can accept this invite'
      using errcode = '42501';
  end if;

  insert into public.team_members
       (team_id, user_id, role,                          jersey_number, added_by)
  values (v_team_id, v_invitee_id, coalesce(v_role, 'player'), v_jersey,      v_invited_by)
  returning membership_id into v_membership_id;

  update public.team_invites
     set status     = 'approved',
         decided_by = v_uid,
         decided_at = now()
   where invite_id = p_invite_id;

  return v_membership_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_team_join_request(p_request_id uuid, p_jersey_number integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid           uuid := auth.uid();
  v_team_id       uuid;
  v_player_id     uuid;
  v_role          text;
  v_membership_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select team_id, player_id, role
    into v_team_id, v_player_id, v_role
    from public.team_join_requests
   where request_id = p_request_id and status = 'pending'
   for update;

  if v_team_id is null then
    raise exception 'Join request not found or not pending' using errcode = 'P0002';
  end if;

  if not public.is_team_manager(v_team_id) then
    raise exception 'Only team managers can approve join requests' using errcode = '42501';
  end if;

  insert into public.team_members (team_id, user_id, role, jersey_number, added_by)
  values (v_team_id, v_player_id, coalesce(v_role, 'player'), p_jersey_number, v_uid)
  returning membership_id into v_membership_id;

  update public.team_join_requests
     set status = 'approved',
         decided_by = v_uid,
         decided_at = now()
   where request_id = p_request_id;

  return v_membership_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_team_member(p_team_id uuid, p_user_id uuid, p_role_key text DEFAULT 'player'::text, p_jersey_number integer DEFAULT NULL::integer, p_in_squad boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid        uuid := auth.uid();
  v_membership uuid;
  v_rank       integer;
  v_caller     integer;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if not public.can('team', p_team_id, 'team.roster.write') then
    raise exception 'Not allowed to add players to this team' using errcode = '42501';
  end if;

  -- You may not seat someone at or above your own rung.
  select rank into v_rank from public.roles where scope='team' and key = p_role_key;
  select max(r.rank) into v_caller
    from public.team_members tm
    join public.team_member_roles tmr on tmr.membership_id = tm.membership_id
    join public.roles r on r.scope = tmr.scope and r.key = tmr.role_key
   where tm.team_id = p_team_id and tm.user_id = v_uid and tm.status = 'active';

  if v_rank is null then
    raise exception 'No such team role "%"', p_role_key using errcode = 'P0002';
  end if;
  if coalesce(v_caller, -1) <= v_rank then
    raise exception 'Cannot grant a role at or above your own' using errcode = '42501';
  end if;

  perform set_config('matchday.initial_role', p_role_key, true);

  insert into public.team_members (team_id, user_id, jersey_number, in_squad, added_by)
  values (p_team_id, p_user_id, p_jersey_number, p_in_squad, v_uid)
  returning membership_id into v_membership;

  return v_membership;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_team_member_to_chat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_chat_id uuid;
begin
  if new.user_id is null then return new; end if;
  if new.status  <> 'active' then return new; end if;

  select chat_id into v_chat_id
    from public.chats
   where team_id = new.team_id and type = 'team';
  if v_chat_id is null then return new; end if;

  insert into public.chat_members (chat_id, user_id, role)
  values (v_chat_id, new.user_id, 'member')
  on conflict (chat_id, user_id)
  do update set left_at = null;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_to_match_pool(p_request_id uuid, p_applicant_team_id uuid, p_applicant_xi uuid[] DEFAULT '{}'::uuid[], p_applicant_keeper_id uuid DEFAULT NULL::uuid, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req            public.match_challenges%rowtype;
  v_app_id         uuid;
  v_applicant_name text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if not public.is_team_manager(p_applicant_team_id) then
    raise exception 'You can only apply on behalf of teams you manage'
      using errcode = '42501';
  end if;

  select * into v_req from public.match_challenges
   where request_id = p_request_id
   for share;

  if not found then
    raise exception 'Match request not found' using errcode = 'P0002';
  end if;

  if v_req.to_team_id is not null then
    raise exception 'This is a direct 1-to-1 challenge, not an open pool post'
      using errcode = '22023';
  end if;

  if v_req.status != 'pending' then
    raise exception 'This open match request is no longer accepting applications (status: %)', v_req.status
      using errcode = '22023';
  end if;

  if v_req.from_team_id = p_applicant_team_id then
    raise exception 'A team cannot apply to its own open challenge'
      using errcode = '23514';
  end if;

  -- Validate applicant squad members
  perform public._validate_team_xi(p_applicant_team_id, p_applicant_xi);

  -- Check if team has already applied and is pending
  if exists (
    select 1 from public.match_pool_applications
     where request_id = p_request_id
       and applicant_team_id = p_applicant_team_id
       and status = 'pending'
  ) then
    raise exception 'Your team has already applied to this open challenge'
      using errcode = '23505';
  end if;

  insert into public.match_pool_applications (
    request_id,
    applicant_team_id,
    applicant_user_id,
    applicant_xi,
    applicant_keeper_id,
    message,
    status
  ) values (
    p_request_id,
    p_applicant_team_id,
    auth.uid(),
    coalesce(p_applicant_xi, '{}'::uuid[]),
    p_applicant_keeper_id,
    p_message,
    'pending'
  )
  returning application_id into v_app_id;

  -- Notify the host team's staff. The applicant's name is no longer looked up
  -- here: notify() resolves {{opponent_name}} from opponent_team_id, so the
  -- sentence lives in the catalogue instead of being concatenated into the
  -- payload as a 'message' key the client had to know to read.
  perform public.notify(
    array(select public.team_staff_ids(v_req.from_team_id)),
    'match.application.received',
    jsonb_build_object(
      'request_id',        p_request_id,
      'from_team_id',      v_req.from_team_id,
      'applicant_team_id', p_applicant_team_id,
      'opponent_team_id',  p_applicant_team_id,
      'actor_id',          auth.uid()
    ),
    auth.uid(), 'team', v_req.from_team_id
  );

  return v_app_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_claim_request(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid           uuid := auth.uid();
  v_unclaimed_id  uuid;
  v_requester_id  uuid;
  v_added_by      uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select cr.unclaimed_id, cr.requester_id, up.added_by
    into v_unclaimed_id, v_requester_id, v_added_by
    from public.claim_requests cr
    join public.unclaimed_players up on up.unclaimed_id = cr.unclaimed_id
   where cr.request_id = p_request_id and cr.status = 'pending'
   for update;
  if v_unclaimed_id is null then
    raise exception 'Claim request not found or not pending'
      using errcode = 'P0002';
  end if;
  if v_added_by <> v_uid then
    raise exception 'Only the manager who added this player can approve'
      using errcode = '42501';
  end if;

  -- Setting claimed_by_user_id fires cascade_unclaimed_claim (0210), which
  -- rewrites team_members and calls migrate_player_stats.
  update public.unclaimed_players
     set claimed_by_user_id = v_requester_id
   where unclaimed_id = v_unclaimed_id;

  update public.claim_requests
     set status     = 'approved',
         decided_by = v_uid,
         decided_at = now()
   where request_id = p_request_id;
end;
$function$

