CREATE OR REPLACE FUNCTION public.bump_comment_likes_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    update public.comments set likes_count = likes_count + 1
     where comment_id = new.comment_id;
    return new;
  elsif tg_op = 'DELETE' then
    update public.comments set likes_count = greatest(likes_count - 1, 0)
     where comment_id = old.comment_id;
    return old;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.bump_post_comments_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.status = 'active' then
      update public.posts set comments_count = comments_count + 1
       where post_id = new.post_id;
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if old.status = 'active' and new.status <> 'active' then
      update public.posts set comments_count = greatest(comments_count - 1, 0)
       where post_id = new.post_id;
    elsif old.status <> 'active' and new.status = 'active' then
      update public.posts set comments_count = comments_count + 1
       where post_id = new.post_id;
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    if old.status = 'active' then
      update public.posts set comments_count = greatest(comments_count - 1, 0)
       where post_id = old.post_id;
    end if;
    return old;
  end if;
  return null;
end;
$function$

