CREATE OR REPLACE FUNCTION public.cancel_match_request(p_request_id uuid, p_decision_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req     public.match_challenges%rowtype;
  v_updated integer;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into v_req from public.match_challenges
   where request_id = p_request_id
   for update;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if v_req.status not in ('pending', 'countered') then
    raise exception 'Request is no longer actionable (status: %)', v_req.status
      using errcode = '22023';
  end if;
  if not public.is_team_manager(v_req.from_team_id) then
    raise exception 'Only managers of the requesting team can cancel'
      using errcode = '42501';
  end if;

  update public.match_challenges
     set status        = 'cancelled',
         decided_by    = auth.uid(),
         decided_at    = now(),
         decision_note = p_decision_note
   where request_id = p_request_id
     and status     = v_req.status;
  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    raise exception 'Request changed under us; aborting cancel'
      using errcode = '40001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_unclaimed_by_phone()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_phone text;
  v_claimed_count int := 0;
  v_rec record;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select phone into v_phone from auth.users where id = auth.uid();
  if v_phone is null or length(trim(v_phone)) = 0 then
    return 0;
  end if;

  v_phone := '+' || ltrim(trim(v_phone), '+');

  for v_rec in
    select unclaimed_id from public.unclaimed_players
    where (phone_number = v_phone or phone_number = ltrim(v_phone, '+'))
      and claimed_by_user_id is null
  loop
    update public.unclaimed_players
    set claimed_by_user_id = auth.uid(),
        claimed_at = now()
    where unclaimed_id = v_rec.unclaimed_id;

    v_claimed_count := v_claimed_count + 1;
  end loop;

  return v_claimed_count;
end;
$function$

