CREATE OR REPLACE FUNCTION public.counter_match_request(p_request_id uuid, p_countered_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_countered_venue text DEFAULT NULL::text, p_countered_format jsonb DEFAULT NULL::jsonb, p_countered_players_per_side integer DEFAULT NULL::integer, p_decision_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req     public.match_challenges%rowtype;
  v_updated integer;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into v_req from public.match_challenges
   where request_id = p_request_id
   for update;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'Only pending requests can be countered (status: %)', v_req.status
      using errcode = '22023';
  end if;
  if v_req.to_team_id is null then
    raise exception 'Open requests cannot be countered; claim with desired terms instead'
      using errcode = '22023';
  end if;
  if not public.is_team_manager(v_req.to_team_id) then
    raise exception 'Only managers of the receiving team can counter'
      using errcode = '42501';
  end if;
  if p_countered_players_per_side is not null
     and (p_countered_players_per_side < 5 or p_countered_players_per_side > 15) then
    raise exception 'players_per_side must be between 5 and 15' using errcode = '22023';
  end if;
  if p_countered_start_time is null and p_countered_venue is null
     and p_countered_format is null and p_countered_players_per_side is null then
    raise exception 'A counter must change at least one field' using errcode = '22023';
  end if;

  -- Race guard: only transition if we still observe 'pending'. A concurrent
  -- accept_match_request that's already moved the row to 'accepted' will
  -- cause this UPDATE to match zero rows and we abort cleanly.
  update public.match_challenges
     set status                     = 'countered',
         decided_by                 = auth.uid(),
         decided_at                 = now(),
         decision_note              = p_decision_note,
         countered_start_time       = p_countered_start_time,
         countered_venue            = p_countered_venue,
         countered_format           = p_countered_format,
         countered_players_per_side = p_countered_players_per_side,
         -- Counter timer is restarted from THIS moment, not from the
         -- original send. The countered party gets a fresh 24h to decide.
         counter_expires_at         = now() + interval '24 hours'
   where request_id = p_request_id
     and status     = 'pending';
  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    raise exception 'Request changed under us; aborting counter'
      using errcode = '40001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_owner_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_membership uuid;
begin
  if new.created_by is null then
    return new;
  end if;

  -- Declare the intent; assign_initial_role() attaches exactly this role, so
  -- the membership never passes through a `player` state that would collide
  -- with the {owner, manager, player} exclusion set.
  perform set_config('matchday.initial_role', 'owner', true);

  insert into public.team_members (team_id, user_id, in_squad, added_by)
  values (new.team_id, new.created_by, true, new.created_by)
  returning membership_id into v_membership;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.decline_dm_request(p_chat_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'Unauthenticated';
  end if;

  -- Ensure actor is a participant in this DM
  if not exists (
    select 1 from public.dm_channels
     where chat_id = p_chat_id
       and (user_a = v_actor or user_b = v_actor)
  ) then
    raise exception 'Not a participant in this DM chat';
  end if;

  -- Soft remove from chat for recipient
  update public.chat_members
     set left_at = now()
   where chat_id = p_chat_id
     and user_id = v_actor;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.decline_match_request(p_request_id uuid, p_decision_note text DEFAULT NULL::text, p_decision_reason decline_reason DEFAULT NULL::decline_reason)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_req     public.match_challenges%rowtype;
  v_updated integer;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into v_req from public.match_challenges
   where request_id = p_request_id
   for update;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;

  if v_req.status = 'pending' then
    if v_req.to_team_id is null then
      raise exception 'Open requests cannot be declined; cancel from sender side instead'
        using errcode = '22023';
    end if;
    if not public.is_team_manager(v_req.to_team_id) then
      raise exception 'Only managers of the receiving team can decline'
        using errcode = '42501';
    end if;
  elsif v_req.status = 'countered' then
    if not public.is_team_manager(v_req.from_team_id) then
      raise exception 'Only the original sender can decline a countered request'
        using errcode = '42501';
    end if;
  else
    raise exception 'Request is no longer actionable (status: %)', v_req.status
      using errcode = '22023';
  end if;

  update public.match_challenges
     set status          = 'declined',
         decided_by      = auth.uid(),
         decided_at      = now(),
         decision_note   = p_decision_note,
         decision_reason = p_decision_reason
   where request_id = p_request_id
     and status     = v_req.status;
  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    raise exception 'Request changed under us; aborting decline'
      using errcode = '40001';
  end if;
end;
$function$

