CREATE OR REPLACE FUNCTION public.enforce_comment_single_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_parent_post   uuid;
  v_parent_parent uuid;
begin
  if new.parent_comment_id is null then
    return new;
  end if;
  select post_id, parent_comment_id
    into v_parent_post, v_parent_parent
    from public.comments
   where comment_id = new.parent_comment_id;
  if v_parent_post is null then
    raise exception 'Parent comment % not found', new.parent_comment_id
      using errcode = 'P0002';
  end if;
  if v_parent_post <> new.post_id then
    raise exception 'Reply must belong to the same post as its parent'
      using errcode = '23514';
  end if;
  if v_parent_parent is not null then
    raise exception 'Single-level threading only — cannot reply to a reply'
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_username_cooldown()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.username is distinct from old.username
     and old.username is not null
     and old.username_changed_at is not null
     and old.username_changed_at > now() - interval '30 days' then
    raise exception 'Username can be changed only once every 30 days.'
      using errcode = 'check_violation';
  end if;
  if new.username is distinct from old.username then
    new.username_changed_at = now();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.find_match_request_by_code(p_code text)
 RETURNS SETOF match_challenges
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.match_challenges%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into v_row
    from public.match_challenges
   where share_code      = p_code
     and status          in ('pending', 'countered')
     and code_expires_at > now()
   limit 1;

