CREATE OR REPLACE FUNCTION public.get_or_create_dm_chat(p_target_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_user_a uuid;
  v_user_b uuid;
  v_chat_id uuid;
begin
  if v_actor is null then
    raise exception 'Unauthenticated';
  end if;

  if p_target_user_id is null or p_target_user_id = v_actor then
    raise exception 'Cannot create DM with self or null target';
  end if;

  -- Canonical ordering
  if v_actor < p_target_user_id then
    v_user_a := v_actor;
    v_user_b := p_target_user_id;
  else
    v_user_a := p_target_user_id;
    v_user_b := v_actor;
  end if;

  -- Check if DM channel already exists
  select chat_id into v_chat_id
    from public.dm_channels
   where user_a = v_user_a
     and user_b = v_user_b;

  if v_chat_id is not null then
    return v_chat_id;
  end if;

  -- Create new chat container
  insert into public.chats (type)
  values ('dm')
  returning chat_id into v_chat_id;

  -- Insert pairing row
  insert into public.dm_channels (chat_id, user_a, user_b)
  values (v_chat_id, v_user_a, v_user_b);

  -- Insert both members into chat_members
  insert into public.chat_members (chat_id, user_id, role)
  values
    (v_chat_id, v_actor, 'member'),
    (v_chat_id, p_target_user_id, 'member')
  on conflict (chat_id, user_id) do nothing;

  return v_chat_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_team_role(p_membership_id uuid, p_role_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid       uuid := auth.uid();
  v_team_id   uuid;
  v_target    uuid;
  v_rank      integer;
  v_min_rank  integer;
  v_mine      integer;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if p_role_key = 'owner' then
    raise exception 'Use transfer_team_ownership() to move ownership'
      using errcode = '42501';
  end if;

  select tm.team_id, tm.user_id into v_team_id, v_target
    from public.team_members tm
   where tm.membership_id = p_membership_id and tm.status = 'active'
   for update;
  if v_team_id is null then
    raise exception 'No such active membership' using errcode = 'P0002';
  end if;

  select rank into v_rank from public.roles where scope='team' and key = p_role_key;
  if v_rank is null then
    raise exception 'No such team role "%"', p_role_key using errcode = 'P0002';
  end if;

  -- Which permission is needed depends on how powerful the role is.
  select min_rank into v_min_rank from public.permissions
   where permission_key = 'team.staff.appoint';
  if v_rank >= coalesce(v_min_rank, 40) - 10 then
    if not public.can('team', v_team_id, 'team.staff.appoint') then
      raise exception 'Only the team owner can appoint staff' using errcode = '42501';
    end if;
  elsif not public.can('team', v_team_id, 'team.roster.role') then
    raise exception 'Not allowed to change roles on this team' using errcode = '42501';
  end if;

  v_mine := public._my_rank(v_team_id);
  if v_mine <= v_rank then
    raise exception 'Cannot grant a role at or above your own rank'
      using errcode = '42501';
  end if;
  if v_target is distinct from v_uid
     and v_mine <= public._member_rank(p_membership_id) then
    raise exception 'Cannot change the roles of someone at or above your own rank'
      using errcode = '42501';
  end if;

  -- Nobody's role change may strip `owner` — least of all the owner's own.
  -- `owner` shares the {owner, manager, player} exclusion set, so "make me a
  -- manager" used to delete the owner row and hand back a team with ZERO
  -- owners: no one holding the short-circuit in can(), so no one able to
  -- disband it, appoint staff or hand it on. leave_team() already refuses an
  -- owner for the same reason, and the repository contract promises this one
  -- does too. Ownership moves through transfer_team_ownership, or not at all.
  if exists (
    select 1 from public.team_member_roles
     where membership_id = p_membership_id and scope = 'team' and role_key = 'owner'
  ) and exists (
    select 1
      from public.role_exclusion_members a
      join public.role_exclusion_members b on b.set_id = a.set_id
     where a.scope = 'team' and a.role_key = 'owner'
       and b.scope = 'team' and b.role_key = p_role_key
  ) then
    raise exception 'Transfer ownership before changing the owner''s role'
      using errcode = '42501';
  end if;

  -- Granting a role that shares an exclusion set with one they already hold
  -- REPLACES it. That is what "at most one of these" means in practice: making
  -- someone a manager is exactly making them stop being a player.
  --
  -- Doing it here rather than making callers pre-revoke matters: the two
  -- statements have to be one transaction (the at-least-one-role check is
  -- deferred precisely so they can be), and leaving that to every call site is
  -- how you get a half-promoted member. The SSD trigger still guards every
  -- other write path — see the direct-insert case in the test suite.
  delete from public.team_member_roles tmr
   where tmr.membership_id = p_membership_id
     and tmr.role_key <> p_role_key
     and exists (
       select 1
         from public.role_exclusion_members a
         join public.role_exclusion_members b on b.set_id = a.set_id
        where a.scope = tmr.scope and a.role_key = tmr.role_key
          and b.scope = 'team'    and b.role_key = p_role_key
     );

  perform public._attach_role(p_membership_id, p_role_key, v_uid);
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_chat_members_role_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if new.role is distinct from old.role then
    if not exists (
      select 1 from public.chat_members admin
       where admin.chat_id = old.chat_id
         and admin.user_id = v_actor
         and admin.role    = 'admin'
         and admin.left_at is null
    ) then
      raise exception 'Only active chat admins can change member roles';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_dm_message_request_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_chat_type public.chat_type;
  v_other_user uuid;
  v_accepted_at timestamptz;
  v_they_follow boolean;
  v_prior_count int;
begin
  select type into v_chat_type from public.chats where chat_id = new.chat_id;
  if v_chat_type <> 'dm' then
    return new;
  end if;

  -- Find other participant in DM
  select
    case when user_a = new.sender_id then user_b else user_a end,
    accepted_at
  into v_other_user, v_accepted_at
  from public.dm_channels
  where chat_id = new.chat_id;

  if v_other_user is null then
    return new;
  end if;

  -- If already accepted, no restriction
  if v_accepted_at is not null then
    return new;
  end if;

  -- Check if other user follows sender
  select exists (
    select 1 from public.follows
     where follower_id = v_other_user
       and target_type = 'user'
       and target_id = new.sender_id
  ) into v_they_follow;

  -- If they follow the sender, auto-accepted / no restriction
  if v_they_follow then
    return new;
  end if;

  -- Count prior non-deleted messages from this sender in this chat
  select count(*) into v_prior_count
    from public.messages
   where chat_id = new.chat_id
     and sender_id = new.sender_id
     and deleted_at is null;

  if v_prior_count >= 1 then
    raise exception 'Cannot send more messages until the recipient accepts your message request';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_exclusion_set_sane()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_set_id uuid := coalesce(new.set_id, old.set_id);
  v_count  integer;
  v_max    integer;
begin
  select count(*) into v_count
    from public.role_exclusion_members where set_id = v_set_id;
  select max_roles into v_max
    from public.role_exclusion_sets where set_id = v_set_id;

  -- An empty or single-role set is inert, not broken — allow it while a set is
  -- being assembled. Only a set that cannot constrain anything is an error.
  if v_count > 1 and v_max >= v_count then
    raise exception
      'Exclusion set % allows % of % roles — it constrains nothing',
      v_set_id, v_max, v_count
      using errcode = '23514';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_grant_is_grantable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (
    select 1 from public.permissions
     where permission_key = new.permission_key and direct_grantable
  ) then
    raise exception
      'Permission % cannot be granted directly; it is role-only',
      new.permission_key
      using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_member_has_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_membership uuid := coalesce(new.membership_id, old.membership_id);
begin
  if not exists (
    select 1 from public.team_members
     where membership_id = v_membership and status = 'active'
  ) then
    return null;   -- membership gone or inactive: nothing to check
  end if;
  if not exists (
    select 1 from public.team_member_roles where membership_id = v_membership
  ) then
    raise exception 'A team member must hold at least one role'
      using errcode = '23514';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_permission_min_rank()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_min  integer;
  v_rank integer;
begin
  if not new.granted then
    return new;   -- revoking is always allowed
  end if;
  select min_rank into v_min
    from public.permissions where permission_key = new.permission_key;
  if v_min is null then
    return new;
  end if;
  select rank into v_rank
    from public.roles where scope = new.scope and key = new.role_key;

  if v_rank < v_min then
    raise exception
      'Permission % requires rank >= %; role % has rank %',
      new.permission_key, v_min, new.role_key, v_rank
      using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_role_needs_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_allows  boolean;
begin
  select user_id into v_user_id
    from public.team_members where membership_id = new.membership_id;
  if v_user_id is not null then
    return new;
  end if;
  select allows_unclaimed into v_allows
    from public.roles where scope = new.scope and key = new.role_key;
  if not coalesce(v_allows, false) then
    raise exception
      'Role "%" requires a MatchDay account; this member is an unclaimed placeholder',
      new.role_key
      using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.leave_team(p_membership_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid            uuid := auth.uid();
  v_member_user_id uuid;
  v_is_owner       boolean;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select tm.user_id,
         exists (select 1 from public.team_member_roles tmr
                  where tmr.membership_id = tm.membership_id and tmr.role_key = 'owner')
    into v_member_user_id, v_is_owner
    from public.team_members tm
   where tm.membership_id = p_membership_id and tm.status = 'active'
   for update;

  if v_member_user_id is null or v_member_user_id <> v_uid then
    raise exception 'Cannot leave a membership that is not yours' using errcode = '42501';
  end if;
  if v_is_owner then
    raise exception 'Transfer ownership before leaving the team' using errcode = '42501';
  end if;

  -- Roles are a live assignment, not history: they go with the membership.
  delete from public.team_member_roles where membership_id = p_membership_id;

  update public.team_members
     set status = 'inactive', left_at = now()
   where membership_id = p_membership_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.mirror_scorer_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.role = 'scorer' then
      delete from public.grants
       where subject_id = old.user_id
         and scope = 'match' and entity_id = old.match_id
         and permission_key = 'match.score';
    end if;
    return old;
  end if;

  if new.role = 'scorer' then
    insert into public.grants
      (subject_id, scope, entity_id, permission_key, granted_by)
    values
      (new.user_id, 'match', new.match_id, 'match.score', new.assigned_by)
    on conflict (subject_id, scope, entity_id, permission_key) do nothing;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify(p_recipients uuid[], p_type_key text, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid, p_scope text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_type         public.notification_types%rowtype;
  v_icon_path    text;
  v_recipient    uuid;
  v_vars         jsonb;
  v_title        text;
  v_body         text;
  v_route        text;
  v_collapse     text;
  v_inapp_def    boolean;
  v_push_def     boolean;
  v_all_ids      uuid[];
  v_push_ids     uuid[];
begin
  -- 0. Validate before anything else. Fail closed and loud.
  select * into v_type
    from public.notification_types
   where key = p_type_key and is_active;
  if not found then
    raise exception
      'notify(): unknown or inactive notification type "%"', p_type_key
      using errcode = '22023';
  end if;

  if p_recipients is null or cardinality(p_recipients) = 0 then
    return;
  end if;

  v_vars     := public._notify_vars(p_payload, p_actor_id);
  v_title    := public.render_template(v_type.title_template,    v_vars);
  v_body     := public.render_template(v_type.body_template,     v_vars);
  v_route    := public.render_template(v_type.route_template,    v_vars);
  v_collapse := public.render_template(v_type.collapse_template, v_vars);

  select storage_path into strict v_icon_path from public.notification_icons where key = v_type.icon;

  -- Serialize only competing groups. Sorted recipient locks avoid deadlocks
  -- for overlapping fan-outs. Expiry releases the unique key without marking
  -- historical notifications read or discarding their contents.
  if nullif(v_collapse, '') is not null then
    for v_recipient in select distinct id from unnest(p_recipients) r(id)
      where id is not null order by id
    loop
      perform pg_advisory_xact_lock(hashtextextended(v_recipient::text || ':' || v_collapse, 0));
    end loop;
    update public.notifications set collapse_key = null
      where recipient_id = any(p_recipients) and collapse_key = v_collapse
        and not is_read and collapse_until <= now();
  end if;

  v_inapp_def := 'inapp' = any(v_type.default_channels);
  v_push_def  := 'push'  = any(v_type.default_channels);

  with targets as (
    select distinct r.id as recipient_id
      from unnest(p_recipients) as r(id)
     where r.id is not null
       -- 1. never notify the actor about their own action
       and (p_actor_id is null or r.id <> p_actor_id)
       -- 2. entity mute
       and (not v_type.user_configurable or not exists (
         select 1
           from public.notification_mutes m
          where m.user_id   = r.id
            and p_scope     is not null
            and m.scope     = p_scope
            and m.entity_id = p_entity_id
            and (m.muted_until is null or m.muted_until > now())
       )
       )
       -- 3. in-app category preference; absent row ⇒ the type's default
       and (not v_type.user_configurable or coalesce(
         (select pp.enabled
            from public.notification_preferences pp
           where pp.user_id  = r.id
             and pp.category = v_type.category
             and pp.channel  = 'inapp'),
         v_inapp_def
       ))
  ),
  ins as (
    insert into public.notifications (
      recipient_id, type_key, title, body, route, tier, icon, icon_path, tone,
      actor_id, entity_scope, entity_id, payload, collapse_key, collapse_until
    )
    select t.recipient_id, v_type.key, v_title, v_body, v_route,
           -- Presentation is snapshotted with rendered copy.
           v_type.tier, v_type.icon, v_icon_path, v_type.tone,
           p_actor_id, p_scope, p_entity_id, coalesce(p_payload, '{}'::jsonb),
           nullif(v_collapse, ''), now() + v_type.collapse_window
      from targets t
    on conflict (recipient_id, collapse_key)
      where collapse_key is not null and is_read = false
    do update set
      group_count = public.notifications.group_count + 1,
      -- Re-render the summary line with the NEW count. group_count is still
      -- the old value here, and "Ali and 1 other" is exactly old-count others.
      body = coalesce(
               public.render_template(
                 v_type.body_template_grouped,
                 v_vars || jsonb_build_object(
                   -- {{count}} is the NEW total and is what grouped copy should
                   -- normally use: a grouped body only ever renders at 2+, so
                   -- "3 people liked your post" is grammatical at every value.
                   -- {{others}} (the count EXCLUDING the named actor) is kept
                   -- for phrasings that name someone, but it needs the template
                   -- to handle "1 other" vs "2 others" itself.
                   'count',  public.notifications.group_count + 1,
                   'others', public.notifications.group_count)),
               excluded.body),
      icon       = excluded.icon,
      icon_path  = excluded.icon_path,
      tone       = excluded.tone,
      tier       = excluded.tier,
      title      = excluded.title,
      route      = excluded.route,
      actor_id   = excluded.actor_id,
      payload    = excluded.payload,
      updated_at = now()
    returning notification_id, recipient_id
  )
  select array_agg(i.notification_id),
         array_agg(i.notification_id)
           filter (where case when v_type.user_configurable then coalesce(pp.enabled, v_push_def) else v_push_def end)
    into v_all_ids, v_push_ids
    from ins i
    left join public.notification_preferences pp
      on  pp.user_id  = i.recipient_id
      and pp.category = v_type.category
      and pp.channel  = 'push';

  if v_all_ids is null then
    return;
  end if;

  insert into public.notification_deliveries
    (notification_id, revision, device_key, channel, status, attempts)
  select n.notification_id, n.group_count, '', 'push', 'skipped_pref', 0
    from public.notifications n where n.notification_id = any(v_all_ids)
      and not (n.notification_id = any(coalesce(v_push_ids, array[]::uuid[])))
  on conflict do nothing;

  if v_push_ids is not null and cardinality(v_push_ids) > 0 then
    perform public._notify_deliver(v_push_ids, v_type.queue_name);
  end if;

  return query select unnest(v_all_ids);
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_recipient_id uuid;
  v_type_key     text;
  v_payload      jsonb;
begin
  v_payload := jsonb_build_object(
    'post_id',           new.post_id,
    'comment_id',        new.comment_id,
    'parent_comment_id', new.parent_comment_id,
    'actor_id',          new.author_id
  );

  if new.parent_comment_id is null then
    select author_id into v_recipient_id
      from public.posts where post_id = new.post_id;
    v_type_key := 'social.post.commented';
  else
    select author_id into v_recipient_id
      from public.comments where comment_id = new.parent_comment_id;
    v_type_key := 'social.comment.replied';
  end if;

  if v_recipient_id is not null then
    perform public.notify(array[v_recipient_id], v_type_key, v_payload,
                          new.author_id, 'post', new.post_id);
  end if;

  -- Mentions. Skip whoever we just notified above so a post author who is also
  -- mentioned gets one notification, not two. (notify() would dedup WITHIN a
  -- call, but these are two calls with two different types.)
  if coalesce(cardinality(new.mentioned_user_ids), 0) > 0 then
    perform public.notify(
      array(
        select m from unnest(new.mentioned_user_ids) as m
         where v_recipient_id is null or m <> v_recipient_id
      ),
      'social.mention',
      jsonb_build_object('post_id',    new.post_id,
                         'comment_id', new.comment_id,
                         'actor_id',   new.author_id),
      new.author_id, 'post', new.post_id
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_follow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.target_type <> 'user' then
    return new;
  end if;
  perform public.notify(
    array[new.target_id], 'social.follow',
    jsonb_build_object('actor_id', new.follower_id),
    new.follower_id, 'user', new.follower_id
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_match_request_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor        uuid;
  v_notify_team  uuid;
  v_opponent     uuid;
  v_recipients   uuid[];
begin
  if old.status = new.status
     or old.status not in ('pending', 'countered') then
    return new;
  end if;

  v_actor := coalesce(new.decided_by, auth.uid());

  if old.status = 'pending' then
    v_notify_team := new.from_team_id;
    v_opponent    := new.to_team_id;
  else
    v_notify_team := new.to_team_id;
    v_opponent    := new.from_team_id;
  end if;

  if v_notify_team is null then
    return new;
  end if;

  v_recipients := array(select public.team_staff_ids(v_notify_team));
  if old.status = 'pending' and new.requested_by is not null then
    v_recipients := v_recipients || new.requested_by;
  end if;

  perform public.notify(
    v_recipients,
    -- Five catalogue keys, not one type plus a status field in the payload.
    'match.challenge.' || new.status::text,
    jsonb_build_object(
      'request_id',       new.request_id,
      'from_team_id',     new.from_team_id,
      'to_team_id',       new.to_team_id,
      'opponent_team_id', v_opponent,
      'match_id',         new.match_id,
      'actor_id',         v_actor
    ),
    v_actor, 'team', v_notify_team
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_post_like()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_author_id uuid;
begin
  select author_id into v_author_id
    from public.posts where post_id = new.post_id;
  if v_author_id is null then
    return new;
  end if;
  -- notify() drops the actor, so the self-like guard is no longer duplicated
  -- here; passing the actor is what makes that happen.
  perform public.notify(
    array[v_author_id], 'social.post.liked',
    jsonb_build_object('post_id', new.post_id, 'actor_id', new.user_id),
    new.user_id, 'post', new.post_id
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.read_notification_jobs(p_queue text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_jobs jsonb; v_limit int;
begin
  if p_queue not in ('notifications_push', 'notifications_push_bulk') then
    raise exception 'Invalid notification queue';
  end if;
  v_limit := case when p_queue = 'notifications_push' then 50 else 100 end;
  select coalesce(jsonb_agg(jsonb_build_object('msg_id', r.msg_id::text,
    'read_ct', r.read_ct, 'message', r.message)), '[]'::jsonb) into v_jobs
  from pgmq.read(p_queue, 120, v_limit) r;
  return v_jobs;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_tournament_standings(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tournament record;
  v_team record;
  v_matches_played int;
  v_wins int;
  v_losses int;
  v_ties int;
  v_no_results int;
  v_points int;
  v_runs_scored int;
  v_overs_faced numeric(6, 2);
  v_runs_conceded int;
  v_overs_bowled numeric(6, 2);
  v_nrr numeric(6, 3);
  v_bat_rr numeric;
  v_bowl_rr numeric;
  v_max_overs numeric;
begin
  select * into v_tournament
    from public.tournaments
   where tournament_id = p_tournament_id;

  if not found then
    return;
  end if;

  v_max_overs := coalesce((v_tournament.format->>'max_overs')::numeric, 20.0);

  for v_team in
    select team_id, group_id
      from public.tournament_teams
     where tournament_id = p_tournament_id
       and status = 'approved'
  loop
    v_matches_played := 0;
    v_wins := 0;
    v_losses := 0;
    v_ties := 0;
    v_no_results := 0;
    v_points := 0;
    v_runs_scored := 0;
    v_overs_faced := 0;
    v_runs_conceded := 0;
    v_overs_bowled := 0;
    v_nrr := 0.0;

    select
      count(*) filter (
        where m.status in ('completed', 'tied', 'no_result', 'abandoned', 'walkover')
      ),
      count(*) filter (
        where m.status in ('completed', 'walkover') and m.winner_id = v_team.team_id
      ),
      count(*) filter (
        where m.status in ('completed', 'walkover')
          and m.winner_id is not null
          and m.winner_id <> v_team.team_id
      ),
      count(*) filter (where m.status = 'tied'),
      count(*) filter (where m.status in ('no_result', 'abandoned'))
    into
      v_matches_played,
      v_wins,
      v_losses,
      v_ties,
      v_no_results
    from public.matches m
    where m.tournament_id = p_tournament_id
      and (m.team_a_id = v_team.team_id or m.team_b_id = v_team.team_id);

    -- Standard cricket points: Win = 2, Tie/NR = 1, Loss = 0
    v_points := (v_wins * 2) + (v_ties * 1) + (v_no_results * 1);

    select
      coalesce(sum(mis.total_runs), 0),
      coalesce(sum(
        case
          when mis.total_wickets >= 10 then v_max_overs
          else (floor(mis.legal_ball_count / 6) + (mis.legal_ball_count % 6) / 10.0)
        end
      ), 0)
    into v_runs_scored, v_overs_faced
    from public.matches m
    join public.match_innings mi on mi.match_id = m.match_id
    join public.match_innings_state mis on mis.innings_id = mi.innings_id
    where m.tournament_id = p_tournament_id
      and m.status = 'completed'
      -- match_innings stores 'team_a' / 'team_b', not a team id.
      and case mi.batting_team_side
            when 'team_a' then m.team_a_id else m.team_b_id
          end = v_team.team_id;

    select
      coalesce(sum(mis.total_runs), 0),
      coalesce(sum(
        case
          when mis.total_wickets >= 10 then v_max_overs
          else (floor(mis.legal_ball_count / 6) + (mis.legal_ball_count % 6) / 10.0)
        end
      ), 0)
    into v_runs_conceded, v_overs_bowled
    from public.matches m
    join public.match_innings mi on mi.match_id = m.match_id
    join public.match_innings_state mis on mis.innings_id = mi.innings_id
    where m.tournament_id = p_tournament_id
      and m.status = 'completed'
      and case mi.bowling_team_side
            when 'team_a' then m.team_a_id else m.team_b_id
          end = v_team.team_id;

    v_bat_rr := case
      when v_overs_faced > 0 then
        v_runs_scored / (floor(v_overs_faced) + ((v_overs_faced - floor(v_overs_faced)) * 10 / 6.0))
      else 0.0
    end;

    v_bowl_rr := case
      when v_overs_bowled > 0 then
        v_runs_conceded / (floor(v_overs_bowled) + ((v_overs_bowled - floor(v_overs_bowled)) * 10 / 6.0))
      else 0.0
    end;

    v_nrr := round((v_bat_rr - v_bowl_rr)::numeric, 3);

    insert into public.tournament_standings (
      tournament_id, team_id, group_id, matches_played, wins, losses, ties,
      no_results, points, runs_scored, overs_faced, runs_conceded,
      overs_bowled, net_run_rate, updated_at
    ) values (
      p_tournament_id, v_team.team_id, v_team.group_id, v_matches_played,
      v_wins, v_losses, v_ties, v_no_results, v_points, v_runs_scored,
      v_overs_faced, v_runs_conceded, v_overs_bowled, v_nrr, now()
    )
    on conflict (tournament_id, team_id) do update set
      group_id = excluded.group_id,
      matches_played = excluded.matches_played,
      wins = excluded.wins,
      losses = excluded.losses,
      ties = excluded.ties,
      no_results = excluded.no_results,
      points = excluded.points,
      runs_scored = excluded.runs_scored,
      overs_faced = excluded.overs_faced,
      runs_conceded = excluded.runs_conceded,
      overs_bowled = excluded.overs_bowled,
      net_run_rate = excluded.net_run_rate,
      updated_at = now();
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_toss_decision(p_match_id uuid, p_decision toss_decision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_won_by uuid;
  v_phase  public.match_start_phase;
begin
  select toss_won_by, start_phase
    into v_won_by, v_phase
    from public.matches
   where match_id = p_match_id
   for update;

  if not found then
    raise exception 'Match not found' using errcode = 'P0002';
  end if;

  if v_won_by is null then
    raise exception 'The toss winner has not been recorded yet'
      using errcode = '22023';
  end if;

  if not public._is_match_side_captain(p_match_id, v_won_by) then
    raise exception 'Only the captain of the side that won the toss can choose to bat or bowl'
      using errcode = '42501';
  end if;

  if v_phase not in ('toss', 'lineup') then
    raise exception 'The toss decision can no longer be changed once the openers are submitted'
      using errcode = '22023';
  end if;

  update public.matches
     set toss_decision = p_decision,
         start_phase = 'lineup',
         status = 'toss',
         updated_at = now()
   where match_id = p_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_pool_application(p_application_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_app public.match_pool_applications%rowtype;
  v_req public.match_challenges%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select * into v_app from public.match_pool_applications
   where application_id = p_application_id
   for update;

  if not found then
    raise exception 'Application not found' using errcode = 'P0002';
  end if;

  select * into v_req from public.match_challenges
   where request_id = v_app.request_id;

  if not public.is_team_manager(v_req.from_team_id) then
    raise exception 'Only managers of the host team can reject applications'
      using errcode = '42501';
  end if;

  update public.match_pool_applications
     set status        = 'rejected',
         decision_note = p_reason,
         decided_at    = now(),
         updated_at    = now()
   where application_id = p_application_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_tournament_registration(p_registration_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid           uuid := auth.uid();
  v_tournament_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select tournament_id
    into v_tournament_id
    from public.tournament_teams
   where registration_id = p_registration_id and status = 'pending'
   for update;
  if v_tournament_id is null then
    raise exception 'Registration not found or not pending' using errcode = 'P0002';
  end if;
  if not public.is_tournament_organizer(v_tournament_id) then
    raise exception 'Only tournament organizers can reject' using errcode = '42501';
  end if;

  update public.tournament_teams
     set status     = 'rejected',
         decided_by = v_uid,
         decided_at = now()
   where registration_id = p_registration_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_tournament_registration(p_registration_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid           uuid := auth.uid();
  v_tournament_id uuid;
  v_registered_by uuid;
  v_team_id       uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select tournament_id, registered_by, team_id
    into v_tournament_id, v_registered_by, v_team_id
    from public.tournament_teams
   where registration_id = p_registration_id and status = 'pending'
   for update;

  if v_tournament_id is null then
    raise exception 'Registration not found or not pending' using errcode = 'P0002';
  end if;

  if not public.is_tournament_organizer(v_tournament_id) then
    raise exception 'Only tournament organizers can reject' using errcode = '42501';
  end if;

  update public.tournament_teams
     set status          = 'rejected',
         decided_by      = v_uid,
         decided_at      = now(),
         decision_reason = nullif(btrim(coalesce(p_reason, '')), ''),
         updated_at      = now()
   where registration_id = p_registration_id;

  -- Tell the manager who applied, so the reason actually reaches someone.
  if v_registered_by is not null then
    perform public.notify_one(
      v_registered_by, 'tournament.registration.declined',
      jsonb_build_object(
        'tournament_id', v_tournament_id,
        'team_id',       v_team_id,
        'message',       nullif(btrim(coalesce(p_reason, '')), '')
      ),
      v_uid, 'tournament', v_tournament_id
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.render_template(p_tmpl text, p_vars jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_out text := p_tmpl;
  v_key text;
  v_val text;
begin
  if p_tmpl is null then
    return null;
  end if;

  for v_key, v_val in
    select e.k,
           case jsonb_typeof(e.v)
             when 'string' then e.v #>> '{}'
             when 'null'   then ''
             else e.v::text
           end
      from jsonb_each(p_vars) as e(k, v)
  loop
    v_out := replace(v_out, '{{' || v_key || '}}', coalesce(v_val, ''));
  end loop;

  -- Strip anything the vocabulary did not cover, then tidy the double spaces
  -- and stray leading/trailing punctuation a removal can leave behind.
  v_out := regexp_replace(v_out, '\{\{[a-z_]+\}\}', '', 'g');
  v_out := btrim(regexp_replace(v_out, '\s+', ' ', 'g'));
  return v_out;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_to_join_team(p_team_id uuid, p_role text DEFAULT 'player'::text, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_request_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if exists (
    select 1 from public.team_members
     where team_id = p_team_id and user_id = v_uid and status = 'active'
  ) then
    raise exception 'Already a member of this team' using errcode = '23505';
  end if;

  insert into public.team_join_requests (team_id, player_id, role, message)
  values (p_team_id, v_uid, coalesce(p_role, 'player'), p_message)
  returning request_id into v_request_id;

  return v_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_team_role(p_membership_id uuid, p_role_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_team_id uuid;
  v_target  uuid;
  v_rank    integer;
  v_mine    integer;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  -- is_singleton stops a SECOND owner; nothing stops ZERO. Ownership leaves
  -- only by transfer, or by the succession path in delete_user.
  if p_role_key = 'owner' then
    raise exception 'Transfer ownership instead of revoking it' using errcode = '42501';
  end if;

  select tm.team_id, tm.user_id into v_team_id, v_target
    from public.team_members tm
   where tm.membership_id = p_membership_id and tm.status = 'active'
   for update;
  if v_team_id is null then
    raise exception 'No such active membership' using errcode = 'P0002';
  end if;

  select rank into v_rank from public.roles where scope='team' and key = p_role_key;
  v_mine := public._my_rank(v_team_id);

  -- Stepping down from your own non-owner role is always allowed.
  if v_target is distinct from v_uid then
    if not public.can('team', v_team_id, 'team.roster.role') then
      raise exception 'Not allowed to change roles on this team' using errcode = '42501';
    end if;
    if v_mine <= public._member_rank(p_membership_id) then
      raise exception 'Cannot change the roles of someone at or above your own rank'
        using errcode = '42501';
    end if;
  end if;

  delete from public.team_member_roles
   where membership_id = p_membership_id and scope = 'team' and role_key = p_role_key;

  -- Taking away someone's LAST role would trip the at-least-one-role check at
  -- COMMIT. In the domain that is never what "un-captain them" means: they are
  -- still on the team, just not captain any more. Fall back to `player`.
  --
  -- Without this, a member created as captain-only could never be demoted at
  -- all — the caller would have to know to grant a second role first, in the
  -- same transaction, which is a trap rather than an API.
  if not exists (
    select 1 from public.team_member_roles where membership_id = p_membership_id
  ) then
    perform public._attach_role(p_membership_id, 'player', v_uid);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_match_request(p_from_team_id uuid, p_to_team_id uuid DEFAULT NULL::uuid, p_proposed_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_proposed_venue text DEFAULT NULL::text, p_proposed_format jsonb DEFAULT '{}'::jsonb, p_message text DEFAULT NULL::text, p_players_per_side integer DEFAULT 11, p_from_team_xi uuid[] DEFAULT '{}'::uuid[], p_from_team_keeper_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_request_id uuid;
  v_code       text;
  v_attempts   integer := 0;
  v_pps        integer := coalesce(p_players_per_side, 11);
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_to_team_id is not null and p_from_team_id = p_to_team_id then
    raise exception 'A team cannot challenge itself' using errcode = '23514';
  end if;
  if not public.is_team_manager(p_from_team_id) then
    raise exception 'Only managers of the requesting team can send a match request'
      using errcode = '42501';
  end if;
  if v_pps < 5 or v_pps > 15 then
    raise exception 'players_per_side must be between 5 and 15' using errcode = '22023';
  end if;
  if p_from_team_xi is not null and array_length(p_from_team_xi, 1) is not null
     and array_length(p_from_team_xi, 1) > v_pps then
    raise exception 'from_team_xi has more players than players_per_side'
      using errcode = '22023';
  end if;
  perform public._validate_team_xi(p_from_team_id, p_from_team_xi);

  if p_to_team_id is not null and exists (
    select 1 from public.match_challenges
     where from_team_id = p_from_team_id
       and to_team_id   = p_to_team_id
       and status in ('pending', 'countered')
  ) then
    raise exception 'A pending request already exists for these teams'
      using errcode = '23505';
  end if;

  loop
    v_code := lpad((floor(random() * 1000000))::int::text, 6, '0');
    begin
      insert into public.match_challenges (
        from_team_id, to_team_id, requested_by,
        proposed_start_time, proposed_venue, proposed_format, message,
        from_team_xi, from_team_keeper_id,
        share_code, code_expires_at, proposal_expires_at
      ) values (
        p_from_team_id, p_to_team_id, auth.uid(),
        p_proposed_start_time, p_proposed_venue,
        coalesce(p_proposed_format, '{}'::jsonb) || jsonb_build_object('players_per_team', v_pps),
        p_message,
        coalesce(p_from_team_xi, '{}'::uuid[]),
        p_from_team_keeper_id,
        v_code,
        now() + interval '24 hours',
        now() + interval '48 hours'
      )
      returning request_id into v_request_id;
      exit;
    exception when unique_violation then
      v_attempts := v_attempts + 1;
      if v_attempts >= 6 then
        raise;
      end if;
    end;
  end loop;

  return v_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_follow_notifications(p_scope text, p_entity_id uuid, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (select 1 from public.follows where follower_id = (select auth.uid())
    and target_type::text = p_scope and target_id = p_entity_id) then
    raise exception 'Follow this entity to change notifications' using errcode = 'P0002';
  end if;
  if p_enabled then
    delete from public.notification_mutes where user_id = (select auth.uid())
      and scope = p_scope and entity_id = p_entity_id;
  else
    insert into public.notification_mutes(user_id, scope, entity_id)
    values ((select auth.uid()), p_scope, p_entity_id)
    on conflict (user_id, scope, entity_id) do update set muted_until = null;
  end if;
end;
$function$

