CREATE OR REPLACE FUNCTION public.start_innings(p_match_id uuid, p_innings_number integer, p_striker_id uuid, p_non_striker_id uuid, p_bowler_id uuid, p_target integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_innings_id   uuid;
  v_status       public.match_status;
  v_team_a       uuid;
  v_team_b       uuid;
  v_toss_won     uuid;
  v_toss_dec     public.toss_decision;
  -- Team IDS are uuid and side LABELS are text. Keeping them in one variable
  -- is what broke this: a uuid was assigned into a text variable and then
  -- compared back against a uuid column, which is `text = uuid` and has no
  -- operator, so every call failed at runtime.
  v_batting_team uuid;
  v_batting_side text;
  v_bowling_side text;
begin
  if not public._can_score_innings(p_match_id, p_innings_number) then
    raise exception 'Only the batting side can start this innings'
      using errcode = '42501';
  end if;

  select team_a_id, team_b_id, toss_won_by, toss_decision, status
    into v_team_a, v_team_b, v_toss_won, v_toss_dec, v_status
    from public.matches
   where match_id = p_match_id;

  if not found then
    raise exception 'Match not found' using errcode = 'P0002';
  end if;

  if v_status in ('completed', 'abandoned', 'walkover') then
    raise exception 'This match is already finished' using errcode = '22023';
  end if;

  -- Which side bats is decided by the toss, not by the innings number being
  -- odd. The previous version hardcoded odd = team_a, so every match where
  -- team B batted first recorded both innings against the wrong side.
  v_batting_team := case
    when v_toss_won is null or v_toss_dec is null then v_team_a
    when v_toss_dec = 'bat' then v_toss_won
    when v_toss_won = v_team_a then v_team_b
    else v_team_a
  end;

  if p_innings_number % 2 = 0 then
    v_batting_team := case
      when v_batting_team = v_team_a then v_team_b else v_team_a
    end;
  end if;

  v_batting_side := case when v_batting_team = v_team_a then 'team_a' else 'team_b' end;
  v_bowling_side := case when v_batting_team = v_team_a then 'team_b' else 'team_a' end;

  -- The target goes to match_innings_state only. match_innings.target_runs was
  -- a second copy written by this same statement and was dropped 2026-09-06.
  insert into public.match_innings (
    match_id, innings_number, batting_team_side, bowling_team_side
  ) values (
    p_match_id, p_innings_number, v_batting_side, v_bowling_side
  )
  on conflict (match_id, innings_number) do update set
    batting_team_side = excluded.batting_team_side,
    bowling_team_side = excluded.bowling_team_side
  returning innings_id into v_innings_id;

  insert into public.match_innings_state (
    innings_id, match_id, innings_number, striker_id, non_striker_id, bowler_id, target
  ) values (
    v_innings_id, p_match_id, p_innings_number, p_striker_id, p_non_striker_id, p_bowler_id, p_target
  )
  on conflict (innings_id) do update set
    striker_id = p_striker_id,
    non_striker_id = p_non_striker_id,
    bowler_id = p_bowler_id,
    target = coalesce(excluded.target, match_innings_state.target),
    version = match_innings_state.version + 1,
    updated_at = now();

  update public.matches
  set status = 'live', updated_at = now()
  where match_id = p_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_assign_official(p_match_id uuid, p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_match public.matches;
begin
  if p_role not in ('umpire_main', 'umpire_leg', 'umpire_third', 'referee') then
    raise exception 'Use tournament_assign_scorer for the scorer role'
      using errcode = '22023';
  end if;

  v_match := public._require_match_organizer(p_match_id);

  if v_match.status in ('completed', 'abandoned', 'walkover') then
    raise exception 'This match is already finished' using errcode = '22023';
  end if;

  -- One person per role: replace whoever held it.
  delete from public.match_officials
   where match_id = p_match_id and role = p_role;

  -- ...and never let one person hold two roles in the same fixture.
  delete from public.match_officials
   where match_id = p_match_id and user_id = p_user_id and role <> 'scorer';

  insert into public.match_officials (match_id, user_id, role, assigned_by)
  values (p_match_id, p_user_id, p_role, auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_auto_assign_scorers(p_tournament_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_match   record;
  v_person  uuid;
  v_filled  integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if not public.is_tournament_organizer(p_tournament_id) then
    raise exception 'Only tournament organizers can assign scorers'
      using errcode = '42501';
  end if;

  for v_match in
    select m.match_id, m.scheduled_start_time
      from public.matches m
     where m.tournament_id = p_tournament_id
       and m.status in ('scheduled', 'toss')
       and not exists (
         select 1 from public.match_officials mo
          where mo.match_id = m.match_id and mo.role = 'scorer'
       )
     order by m.scheduled_start_time
  loop
    select c.user_id into v_person
      from public.tournament_scorer_candidates(p_tournament_id) c
     where not exists (
       -- Free at this hour: no other fixture within a 4-hour window.
       select 1
         from public.match_officials mo
         join public.matches m2 on m2.match_id = mo.match_id
        where mo.user_id = c.user_id
          and mo.role = 'scorer'
          and m2.scheduled_start_time
                between v_match.scheduled_start_time - interval '4 hours'
                    and v_match.scheduled_start_time + interval '4 hours'
     )
     limit 1;

    if v_person is not null then
      insert into public.match_officials (match_id, user_id, role, assigned_by)
      values (v_match.match_id, v_person, 'scorer', auth.uid())
      on conflict do nothing;
      v_filled := v_filled + 1;
    end if;

    v_person := null;
  end loop;

  return v_filled;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_cancel(p_tournament_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_created_by uuid;
  v_name text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select created_by, tournament_name into v_created_by, v_name
    from public.tournaments where tournament_id = p_tournament_id;

  if not found then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;

  if v_created_by is distinct from auth.uid() then
    raise exception 'Only the tournament creator can cancel it'
      using errcode = '42501';
  end if;

  if p_reason is null or length(btrim(p_reason)) < 10 then
    raise exception 'Cancelling requires a reason of at least 10 characters'
      using errcode = '22023';
  end if;

  -- Void what was never played. Completed scorecards are deliberately left
  -- alone so they keep counting towards player stats.
  update public.matches
     set status = 'no_result',
         updated_at = now()
   where tournament_id = p_tournament_id
     and status in ('scheduled', 'toss', 'live', 'innings_break', 'super_over');

  update public.tournaments
     set status = 'cancelled',
         rules = coalesce(rules, '{}'::jsonb) || jsonb_build_object(
           'cancelled_reason', p_reason,
           'cancelled_at', now(),
           'cancelled_by', auth.uid()
         ),
         updated_at = now()
   where tournament_id = p_tournament_id;

  -- Everyone hears about it immediately.
  perform public.tournament_announce(
    p_tournament_id,
    left('Cancelled: ' || p_reason, 300)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_generate_fixtures(p_tournament_id uuid, p_slots jsonb, p_seed_order uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid       uuid := auth.uid();
  v_t         record;
  v_existing  int;
  v_created   int;
  v_format    jsonb;
  v_count     int;
  v_distinct  int;
  v_bad       int;
  v_ids       jsonb;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if not public.is_tournament_organizer(p_tournament_id) then
    raise exception 'Only tournament organizers can publish fixtures'
      using errcode = '42501';
  end if;

  select status, format into v_t
    from public.tournaments where tournament_id = p_tournament_id;

  if not found then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;

  v_format := v_t.format;

  if v_t.status in ('completed', 'cancelled', 'abandoned') then
    raise exception 'This tournament is closed' using errcode = '22023';
  end if;

  -- Locking the draw is once-only: the dialog says so, and re-running would
  -- duplicate the bracket.
  select count(*) into v_existing
    from public.matches where tournament_id = p_tournament_id;

  if v_existing > 0 then
    raise exception 'The draw is already locked (% fixtures exist)', v_existing
      using errcode = '22023';
  end if;

  if jsonb_typeof(p_slots) <> 'array' or jsonb_array_length(p_slots) = 0 then
    raise exception 'No fixtures to publish' using errcode = '22023';
  end if;

  -- ── Validate the plan before writing any of it ────────────────────────────

  -- Order matters: a payload of all-null slot_ids would otherwise trip the
  -- duplicate check and report the wrong fault.
  select count(*) into v_bad
    from jsonb_array_elements(p_slots) as s(elem)
   where elem->>'slot_id' is null;

  if v_bad > 0 then
    raise exception 'Every fixture needs a slot_id' using errcode = '22023';
  end if;

  select count(*), count(distinct elem->>'slot_id')
    into v_count, v_distinct
    from jsonb_array_elements(p_slots) as s(elem);

  if v_distinct < v_count then
    raise exception 'Duplicate slot_id in the draw' using errcode = '22023';
  end if;

  -- Each side must be either a known team or a feeder. Anything else is a
  -- fixture that can never resolve.
  select count(*) into v_bad
    from jsonb_array_elements(p_slots) as s(elem)
   where (elem->>'team_a_id' is null and elem->>'prev_slot_a' is null)
      or (elem->>'team_b_id' is null and elem->>'prev_slot_b' is null);

  if v_bad > 0 then
    raise exception
      'A fixture has a side that is neither a team nor a feeder'
      using errcode = '22023';
  end if;

  -- Mint a match id per slot. Doing it here rather than letting the default
  -- fire is what lets the feeder columns be written in the same INSERT.
  select jsonb_object_agg(elem->>'slot_id', gen_random_uuid())
    into v_ids
    from jsonb_array_elements(p_slots) as s(elem);

  -- Every feeder must name a slot that is actually in this payload.
  select count(*) into v_bad
    from jsonb_array_elements(p_slots) as s(elem)
   where (elem->>'prev_slot_a' is not null
          and not jsonb_exists(v_ids, elem->>'prev_slot_a'))
      or (elem->>'prev_slot_b' is not null
          and not jsonb_exists(v_ids, elem->>'prev_slot_b'));

  if v_bad > 0 then
    raise exception 'A fixture feeds from a slot that is not in the draw'
      using errcode = '22023';
  end if;

  -- ── Write ─────────────────────────────────────────────────────────────────

  with inserted as (
    insert into public.matches (
      match_id, tournament_id, match_type, match_format, stage, round,
      bracket_round_number, bracket_match_number,
      prev_match_a_id, prev_match_b_id,
      team_a_id, team_b_id, venue, scheduled_start_time,
      format, status, created_by
    )
    select
      (v_ids->>(slot.elem->>'slot_id'))::uuid,
      p_tournament_id,
      'tournament',
      -- Keep the match's own format aligned with the cup's. The wizard writes
      -- a human preset ("T20", "The Hundred"); map it rather than casting,
      -- which would throw on anything that is not already an enum label.
      case lower(coalesce(v_format->>'format_preset', ''))
        when 'odi'          then 'odi'
        when 'the hundred'  then 'the_hundred'
        when 'test'         then 'test'
        when 'custom limited overs' then 'custom_limited'
        else 't20'
      end::public.match_format,
      case
        when slot.elem->>'round' ilike '%final%'
             and slot.elem->>'round' not ilike '%semi%'
             and slot.elem->>'round' not ilike '%quarter%' then 'final'
        when slot.elem->>'round' ilike '%semi%'    then 'semi_final'
        when slot.elem->>'round' ilike '%quarter%' then 'quarter_final'
        else 'group'
      end::public.match_stage,
      slot.elem->>'round',
      (slot.elem->>'bracket_round_number')::int,
      (slot.elem->>'bracket_match_number')::int,
      (v_ids->>(slot.elem->>'prev_slot_a'))::uuid,
      (v_ids->>(slot.elem->>'prev_slot_b'))::uuid,
      (slot.elem->>'team_a_id')::uuid,
      (slot.elem->>'team_b_id')::uuid,
      nullif(slot.elem->>'venue', ''),
      (slot.elem->>'scheduled_start_time')::timestamptz,
      public._normalize_match_format(v_format),
      'scheduled',
      v_uid
    from jsonb_array_elements(p_slots) as slot(elem)
    returning 1
  )
  select count(*) into v_created from inserted;

  -- The order the organiser dragged into IS the draw, so it is recorded in
  -- the same transaction. Read in four places before this, written in none.
  if p_seed_order is not null then
    update public.tournament_teams tt
       set seed_number = ord.pos,
           updated_at  = now()
      from unnest(p_seed_order) with ordinality as ord(team_id, pos)
     where tt.tournament_id = p_tournament_id
       and tt.team_id       = ord.team_id
       and tt.status        = 'approved';
  end if;

  update public.tournaments
     set status = 'upcoming', updated_at = now()
   where tournament_id = p_tournament_id;

  -- Seed the table so standings render from the moment the draw is locked.
  perform public.recalculate_tournament_standings(p_tournament_id);

  return v_created;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_override_result(p_match_id uuid, p_winner_team_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_match public.matches;
begin
  v_match := public._require_match_organizer(p_match_id);

  if p_reason is null or length(btrim(p_reason)) < 10 then
    raise exception 'An override requires a reason of at least 10 characters'
      using errcode = '22023';
  end if;

  if p_winner_team_id is null
     or (p_winner_team_id is distinct from v_match.team_a_id
         and p_winner_team_id is distinct from v_match.team_b_id) then
    raise exception 'Winner must be one of the two teams in this fixture'
      using errcode = '22023';
  end if;

  insert into public.match_result_history (
    match_id, previous_status, new_status, result_payload, reason, recorded_by
  ) values (
    p_match_id, v_match.status, 'completed',
    coalesce(v_match.result, '{}'::jsonb)
      || jsonb_build_object('overridden_to', p_winner_team_id),
    p_reason, auth.uid()
  );

  -- The scorecard itself is left intact; only the recorded outcome moves.
  update public.matches
     set status = 'completed',
         result = coalesce(result, '{}'::jsonb) || jsonb_build_object(
           'winner_team_id', p_winner_team_id,
           'overridden', true,
           'override_reason', p_reason,
           'overridden_by', auth.uid(),
           'overridden_at', now()
         ),
         updated_at = now()
   where match_id = p_match_id;

  perform public.recalculate_tournament_standings(v_match.tournament_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_record_payment(p_registration_id uuid, p_amount_paid numeric, p_channel text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tournament_id uuid;
  v_entry_fee     numeric;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select tt.tournament_id into v_tournament_id
    from public.tournament_teams tt
   where tt.registration_id = p_registration_id;

  if not found then
    raise exception 'Registration not found' using errcode = 'P0002';
  end if;

  if not public.is_tournament_organizer(v_tournament_id) then
    raise exception 'Only tournament organizers can record payments'
      using errcode = '42501';
  end if;

  if p_amount_paid is null or p_amount_paid < 0 then
    raise exception 'Amount must be zero or more' using errcode = '22023';
  end if;

  select coalesce(t.entry_fee, 0) into v_entry_fee
    from public.tournaments t
   where t.tournament_id = v_tournament_id;

  -- Overpayment is a data-entry slip, not a business case worth modelling.
  if v_entry_fee > 0 and p_amount_paid > v_entry_fee then
    raise exception 'Amount exceeds the entry fee of %', v_entry_fee
      using errcode = '22023';
  end if;

  update public.tournament_teams
     set amount_paid         = p_amount_paid,
         payment_channel     = p_channel,
         payment_reference   = nullif(btrim(coalesce(p_reference, '')), ''),
         payment_recorded_at = now(),
         payment_recorded_by = auth.uid(),
         -- Keep the legacy label in step so the registrations tab's "Paid"
         -- chip and the ledger never disagree.
         payment_status      = case
                                 when v_entry_fee > 0
                                  and p_amount_paid >= v_entry_fee then 'paid'
                                 when p_amount_paid > 0            then 'partial'
                                 else 'unpaid'
                               end
   where registration_id = p_registration_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_remove_official(p_match_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform public._require_match_organizer(p_match_id);

  if p_role not in ('umpire_main', 'umpire_leg', 'umpire_third', 'referee') then
    raise exception 'Use tournament_assign_scorer to change the scorer'
      using errcode = '22023';
  end if;

  delete from public.match_officials
   where match_id = p_match_id and role = p_role;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_reschedule_match(p_match_id uuid, p_start timestamp with time zone, p_venue text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_match public.matches;
begin
  v_match := public._require_match_organizer(p_match_id);

  if v_match.status in ('completed', 'walkover') then
    raise exception 'Cannot reschedule a finished match' using errcode = '22023';
  end if;

  update public.matches
     set scheduled_start_time = p_start,
         venue = coalesce(nullif(p_venue, ''), venue),
         updated_at = now()
   where match_id = p_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_revise_match_conditions(p_match_id uuid, p_revised_overs integer, p_bowler_quota integer, p_revised_target integer DEFAULT NULL::integer, p_method text DEFAULT 'run_rate'::text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_match    public.matches;
  v_original integer;
begin
  if p_method not in ('run_rate', 'dls', 'custom', 'none') then
    raise exception 'Unknown target method %', p_method using errcode = '22023';
  end if;

  v_match := public._require_match_organizer(p_match_id);

  if v_match.status in ('completed', 'abandoned', 'walkover', 'no_result') then
    raise exception 'This match is already finished' using errcode = '22023';
  end if;

  -- "Minimum 5 overs per side for a result" (28b). The floor is a competition
  -- rule, not arithmetic, so it belongs to whoever guards the fixture.
  if p_revised_overs is null or p_revised_overs < 5 then
    raise exception 'A result needs at least 5 overs per side'
      using errcode = '22023';
  end if;

  -- `format`, not the former `rules_config`: one format document per match
  -- since the 2026-09-06 consolidation, normalized by _normalize_match_format.
  v_original := coalesce((v_match.format->>'overs_per_innings')::integer, 20);

  if p_revised_overs > v_original then
    raise exception 'Overs can only be reduced, not extended'
      using errcode = '22023';
  end if;

  if p_bowler_quota is null or p_bowler_quota < 1 then
    raise exception 'Each bowler needs at least one over' using errcode = '22023';
  end if;

  update public.matches
     set format = public._normalize_match_format(
                    format || jsonb_build_object(
                      'overs_per_innings',    p_revised_overs,
                      'max_overs_per_bowler', p_bowler_quota
                    )
                  ),
         revised_conditions = jsonb_build_object(
           'applied_at',        now(),
           'applied_by',        auth.uid(),
           'original_overs',    v_original,
           'revised_overs',     p_revised_overs,
           'original_quota',    coalesce(
                                  (v_match.format->>'max_overs_per_bowler')::integer,
                                  4),
           'revised_quota',     p_bowler_quota,
           'revised_target',    p_revised_target,
           'method',            p_method,
           'reason',            nullif(btrim(coalesce(p_reason, '')), '')
         )
   where match_id = p_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_set_coorganizer(p_tournament_id uuid, p_user_id uuid, p_add boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_created_by uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select created_by into v_created_by
    from public.tournaments where tournament_id = p_tournament_id;

  if not found then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;

  if v_created_by is distinct from auth.uid() then
    raise exception 'Only the tournament creator can manage co-organisers'
      using errcode = '42501';
  end if;

  if p_user_id = v_created_by then
    raise exception 'The creator is already an organiser' using errcode = '22023';
  end if;

  if p_add then
    update public.tournaments
       set organizers = (
             select array(select distinct unnest(organizers || p_user_id))
           ),
           updated_at = now()
     where tournament_id = p_tournament_id;

    -- Was 'tournament_post' with reason='coorganizer_added': "an announcement
    -- was posted" used to mean "you were given admin rights".
    perform public.notify_one(
      p_user_id, 'tournament.organizer.added',
      jsonb_build_object('tournament_id', p_tournament_id),
      auth.uid(), 'tournament', p_tournament_id
    );
  else
    update public.tournaments
       set organizers = array_remove(organizers, p_user_id),
           updated_at = now()
     where tournament_id = p_tournament_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_trigger_super_over(p_match_id uuid, p_bats_first_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_match public.matches;
begin
  v_match := public._require_match_organizer(p_match_id);

  if v_match.status <> 'tied' then
    raise exception 'A super over needs a tied match' using errcode = '22023';
  end if;

  if p_bats_first_id is null
     or p_bats_first_id not in (v_match.team_a_id, v_match.team_b_id) then
    raise exception 'Choose one of the two sides to bat first'
      using errcode = '22023';
  end if;

  if not coalesce((v_match.format->>'super_over_enabled')::boolean, true) then
    raise exception 'Super overs are disabled for this tournament'
      using errcode = '22023';
  end if;

  update public.matches
     set status       = 'super_over',
         -- Regulation stays untouched; the super over is a second card on the
         -- same fixture, so the tie is preserved inside result.
         result       = coalesce(result, '{}'::jsonb)
                          || jsonb_build_object(
                               'super_over', jsonb_build_object(
                                 'triggered_at',  now(),
                                 'triggered_by',  auth.uid(),
                                 'bats_first_id', p_bats_first_id
                               )
                             ),
         -- winner_id is derived from `result` by match_sync_winner_id; a tied
         -- result carries no winner_team_id, so it clears itself.
         completed_at = null
   where match_id = p_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.transfer_team_ownership(p_team_id uuid, p_new_owner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid      uuid := auth.uid();
  v_mine     uuid;
  v_theirs   uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  -- Authorize BEFORE the self-transfer short-circuit. Reversed, this returned
  -- success to any caller passing themselves — harmless, but a non-owner being
  -- told "OK" is the kind of answer a client builds wrong UI on.
  select tm.membership_id into v_mine
    from public.team_members tm
    join public.team_member_roles tmr
      on tmr.membership_id = tm.membership_id and tmr.role_key = 'owner'
   where tm.team_id = p_team_id and tm.user_id = v_uid and tm.status = 'active'
   for update;

  if v_mine is null then
    raise exception 'Only the team owner can transfer ownership' using errcode = '42501';
  end if;
  if p_new_owner_id = v_uid then
    return;
  end if;

  select tm.membership_id into v_theirs
    from public.team_members tm
   where tm.team_id = p_team_id and tm.user_id = p_new_owner_id and tm.status = 'active'
   for update;
  if v_theirs is null then
    raise exception 'The new owner must already be an active member of the team'
      using errcode = '42501';
  end if;

  -- Demote first: team_member_roles_singleton_per_team forbids two owners even
  -- momentarily. The outgoing owner becomes a manager; the deferred
  -- at-least-one-role check is satisfied at COMMIT either way.
  delete from public.team_member_roles
   where membership_id = v_mine and scope = 'team' and role_key = 'owner';
  perform public._attach_role(v_mine, 'manager', v_uid);

  delete from public.team_member_roles
   where membership_id = v_theirs and scope = 'team'
     and role_key in ('manager', 'player');
  perform public._attach_role(v_theirs, 'owner', v_uid);
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_sync_match_winner_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.winner_id := nullif(new.result->>'winner_team_id', '')::uuid;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.wake_notification_worker()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_url text; v_key text;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'supabase_url' limit 1;
  select decrypted_secret into v_key from vault.decrypted_secrets where name = 'notification_worker_secret' limit 1;
  if v_url is null or v_key is null then
    raise warning 'Notification worker is not configured; jobs remain queued';
    return;
  end if;
  perform net.http_post(url := rtrim(v_url, '/') || '/functions/v1/send-push',
    headers := jsonb_build_object('content-type', 'application/json', 'x-worker-secret', v_key),
    body := '{}'::jsonb, timeout_milliseconds := 55000);
end;
$function$
